Following @AsMartynas answer, I've used his solution to add a dependecy in build.gradle. To insert the dependecy I had to do some string manipulation, finding the index of `dependencies {` - which is the part of the file where dependencies lives - and replacing it with the content I needed. Here's the final code

```
const { withAppBuildGradle } = require("@expo/config-plugins");

const PLAY_BILLING_LIBRARY_VERSION = "6.0.1"

module.exports = function withAndroidStrategiesPlugin(config) {
  return withAppBuildGradle(config, (config) => {
    const initialIndex = config.modResults.contents.indexOf("dependencies {");

    // Add the billing dependency
    config.modResults.contents =
      config.modResults.contents.slice(0, initialIndex) +
      `dependencies {
    implementation("com.android.billingclient:billing:${PLAY_BILLING_LIBRARY_VERSION}")` +
      config.modResults.contents.slice(initialIndex + "dependencies {".length);

    return config;
  });
};
```

