+    tasks.matching { it.name.startsWith("configureCMake") }.configureEach { configureTask ->
+        def prefabVariant = configureTask.name.contains("RelWithDebInfo") ? "Release" : "Debug"
+        prefabProducerProjects.each { producerPath ->
+            configureTask.dependsOn("\\${producerPath}:prefab\\${prefabVariant}Package")
+        }
+    }
+}
+`;
+
+module.exports = function withAndroidPrefabTaskOrdering(config) {
+  return withAppBuildGradle(config, (config) => {
+    if (config.modResults.language !== "groovy") {
+      return config;
+    }
+
+    if (!config.modResults.contents.includes(marker)) {
+      config.modResults.contents += `\n${gradleWorkaround}\n`;
+    }
+
+    return config;
+  });
