const marker = "// al-toque: order native Prefab packages before app CMake configuration";

const gradleWorkaround = `
${marker}
gradle.projectsEvaluated {
    def prefabProducerProjects = [
        ":react-native-reanimated",
        ":react-native-worklets",
    ]

    tasks.matching { it.name.startsWith("configureCMake") }.configureEach { configureTask ->
